import { useState, type FormEvent } from "react"

import type { AdminTopic } from "../../shared/admin"
import type { TopicCreatePayload } from "../../shared/adminWrite"
import {
  DANGER_BUTTON,
  FormField,
  INPUT_CLASS,
  IssueList,
  NotFoundPanel,
  PageHeading,
  PRIMARY_BUTTON,
  Panel,
  SECONDARY_BUTTON,
  issueMessages,
} from "./shared"
import type { ScreenProps } from "./types"

const EMPTY: TopicCreatePayload = {
  title: "",
  titleZh: "",
  icon: "",
  description: "",
  descriptionZh: "",
}

/**
 * The topic editor, used for both create and edit. The id is generated by the
 * server, so it is shown read-only after the first save and hidden on create.
 */
export function TopicForm({
  route,
  snapshot,
  api,
  navigate,
  refresh,
  notify,
  report,
}: ScreenProps) {
  const topicId = route.screen === "topic" ? route.topicId : null
  const existing =
    topicId === null
      ? undefined
      : snapshot.topics.find((topic) => topic.id === topicId)

  const [values, setValues] = useState<TopicCreatePayload>(() =>
    existing === undefined ? EMPTY : fromTopic(existing),
  )
  const [issues, setIssues] = useState<string[]>([])
  const [busy, setBusy] = useState(false)

  if (topicId !== null && existing === undefined) {
    return <NotFoundPanel message="That topic does not exist." />
  }

  if (existing !== undefined && existing.archivedAt !== null) {
    return (
      <Panel>
        <p className="text-sm font-bold">This topic is archived.</p>
        <p className="mt-1 text-xs text-[var(--admin-muted)]">
          Restore it from the Archived view before editing.
        </p>
        <button
          type="button"
          className={`${SECONDARY_BUTTON} mt-4`}
          onClick={() => navigate({ screen: "archived", tab: "topics" })}
        >
          Open Archived
        </button>
      </Panel>
    )
  }

  function set<K extends keyof TopicCreatePayload>(
    key: K,
    value: TopicCreatePayload[K],
  ): void {
    setValues((current) => ({ ...current, [key]: value }))
  }

  async function save(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault()
    setBusy(true)
    setIssues([])

    try {
      const result =
        existing === undefined
          ? await api.createTopic(values, snapshot.contentVersion)
          : await api.updateTopic(
              existing.id,
              values,
              snapshot.contentVersion,
            )

      await refresh()
      notify(notifyMessage(existing === undefined ? "Topic created" : "Topic saved", result.warnings.length))
      navigate({ screen: "topics" })
    } catch (caught) {
      setIssues(issueMessages(caught))
      report(caught)
    } finally {
      setBusy(false)
    }
  }

  async function archive(): Promise<void> {
    if (existing === undefined) return

    const confirmed = window.confirm(
      `Archive “${existing.title}”? Its packs and words are hidden from children. You can restore it from the Archived view.`,
    )
    if (!confirmed) return

    setBusy(true)

    try {
      await api.setTopicArchived(existing.id, true, snapshot.contentVersion)
      await refresh()
      notify("Topic archived.")
      navigate({ screen: "topics" })
    } catch (caught) {
      report(caught)
    } finally {
      setBusy(false)
    }
  }

  return (
    <>
      <PageHeading
        title={existing === undefined ? "New topic" : "Edit topic"}
        description={
          existing === undefined
            ? "A topic groups the packs learners meet together."
            : `Editing ${existing.title}.`
        }
      />

      <IssueList issues={issues} />

      <form onSubmit={(event) => void save(event)} className="grid gap-5">
        <Panel>
          <div className="grid gap-4 sm:grid-cols-2">
            <FormField label="English title">
              <input
                className={INPUT_CLASS}
                required
                value={values.title}
                onChange={(event) => set("title", event.target.value)}
                placeholder="Craft & Build"
              />
            </FormField>
            <FormField label="Chinese title">
              <input
                className={INPUT_CLASS}
                required
                value={values.titleZh}
                onChange={(event) => set("titleZh", event.target.value)}
                placeholder="手工与建造"
              />
            </FormField>
            <FormField label="Icon" hint="One emoji, typed or pasted.">
              <input
                className={INPUT_CLASS}
                required
                value={values.icon}
                onChange={(event) => set("icon", event.target.value)}
                placeholder="🔨"
              />
            </FormField>
            {existing === undefined ? null : (
              <FormField label="Id" hint="Generated once and never reused.">
                <input className={INPUT_CLASS} readOnly value={existing.id} />
              </FormField>
            )}
          </div>

          <div className="mt-4 grid gap-4">
            <FormField label="English description">
              <textarea
                className={INPUT_CLASS}
                required
                rows={2}
                value={values.description}
                onChange={(event) => set("description", event.target.value)}
              />
            </FormField>
            <FormField label="Chinese description">
              <textarea
                className={INPUT_CLASS}
                required
                rows={2}
                value={values.descriptionZh}
                onChange={(event) => set("descriptionZh", event.target.value)}
              />
            </FormField>
          </div>
        </Panel>

        <div className="flex flex-wrap items-center gap-3">
          <button type="submit" className={PRIMARY_BUTTON} disabled={busy}>
            {busy ? "Saving…" : "Save"}
          </button>
          <button
            type="button"
            className={SECONDARY_BUTTON}
            onClick={() => navigate({ screen: "topics" })}
          >
            Cancel
          </button>
        </div>
      </form>

      {existing === undefined ? null : (
        <div className="mt-8 rounded-[15px] border border-[var(--admin-coral)]/25 bg-white p-5">
          <h2 className="text-sm font-extrabold text-[var(--admin-coral)]">
            Danger zone
          </h2>
          <p className="mt-1 max-w-[640px] text-xs text-[var(--admin-muted)]">
            Archived topics and their packs are hidden from children. You can
            restore them from the Archived view.
          </p>
          <button
            type="button"
            className={`${DANGER_BUTTON} mt-4`}
            disabled={busy}
            onClick={() => void archive()}
          >
            Archive topic
          </button>
        </div>
      )}
    </>
  )
}

function fromTopic(topic: AdminTopic): TopicCreatePayload {
  return {
    title: topic.title,
    titleZh: topic.titleZh,
    icon: topic.icon,
    description: topic.description,
    descriptionZh: topic.descriptionZh,
  }
}

function notifyMessage(action: string, warnings: number): string {
  return warnings === 0
    ? `${action}.`
    : `${action} with ${warnings} editorial ${warnings === 1 ? "warning" : "warnings"}.`
}
